function inverseNormal(p){const a=[-39.6968302866538,220.946098424521,-275.928510446969,138.357751867269,-30.6647980661472,2.50662827745924],b=[-54.4760987982241,161.585836858041,-155.698979859887,66.8013118877197,-13.2806815528857],c=[-0.00778489400243029,-0.322396458041136,-2.40075827716184,-2.54973253934373,4.37466414146497,2.93816398269878],d=[0.00778469570904146,0.32246712907004,2.445134137143,3.75440866190742];if(p<=0)return -4;if(p>=1)return 4;const q=p-.5;if(Math.abs(q)<=.425){const r=.180625-q*q;return q*(((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)}let r=q<0?p:1-p;r=Math.sqrt(-Math.log(r));let x=(((((c[0]*r+c[1])*r+c[2])*r+c[3])*r+c[4])*r+c[5])/((((d[0]*r+d[1])*r+d[2])*r+d[3])*r+1);return q<0?x:-x}
function StatsTraining({go,notify}){const [N,setN]=useState(1000),[method,setMethod]=useState('کوکران'),[conf,setConf]=useState(95),[err,setErr]=useState(5),[p,setP]=useState(50),[lead,setLead]=useState(false);const z=inverseNormal(1-(conf/100)/2);const n0=z*z*(p/100)*(1-p/100)/((err/100)**2);const estimate=Math.ceil(n0/(1+(n0-1)/Math.max(1,N)));return <><Title title="آموزش آمار" desc="یادگیری روش‌های آماری و ابزارهای کاربردی پژوهش"/><div className="container stat-training"><section className="stats-hero"><div><span className="tag">آموزش پژوهش‌محور</span><h2>آمار را برای پژوهش خود یاد بگیرید</h2><p>مفاهیم روش‌شناسی و تحلیل داده را با محتوای آموزشی روشن و کاربردی بیاموزید.</p><button className="btn gold" onClick={()=>setLead(true)}>دریافت راهنمای آموزشی <ArrowLeft/></button></div><div className="stats-hero-art"><BarChart3/><ChartNoAxesColumnIncreasing/><Presentation/></div></section><section className="card calculator"><div><span className="tag">ابزار آنلاین</span><h2>محاسبه آنلاین حجم نمونه از جامعه آماری</h2><p>روش محاسبه را انتخاب کنید و پارامترهای جامعه را وارد نمایید.</p></div><div className="form-grid"><label className="field"><span>روش برآورد</span><select value={method} onChange={e=>setMethod(e.target.value)}><option>کوکران</option><option>مورگان / گرجسی و مورگان</option></select></label><label className="field"><span>حجم جامعه آماری</span><input type="number" min="1" value={N} onChange={e=>setN(+e.target.value||1)}/></label><label className="field"><span>سطح اطمینان</span><input type="number" min="80" max="99.9" step="0.1" value={conf} onChange={e=>setConf(Math.min(99.9,Math.max(80,+e.target.value||95)))}/></label><label className="field"><span>میزان خطا (درصد)</span><input type="number" min="1" max="20" value={err} onChange={e=>setErr(+e.target.value||5)}/></label><label className="field"><span>نسبت صفت (p درصد)</span><input type="number" min="1" max="99" value={p} onChange={e=>setP(+e.target.value||50)}/></label></div><div className="sample-result"><div><small>برآورد حجم نمونه با روش {method}</small><b>{estimate.toLocaleString('fa-IR')} نفر</b></div><small>فرمول با تصحیح جامعه محدود · سطح اطمینان {conf}٪ · خطا {err}٪</small></div><button className="btn gold small" onClick={()=>setLead(true)}>برای تحلیل پژوهش مشاوره بگیرید <ArrowLeft/></button></section><section className="stats-lessons">{[['توصیف داده‌ها','شاخص‌های مرکزی، پراکندگی و نمودارهای مؤثر'],['آزمون فرضیه','انتخاب آزمون مناسب و تفسیر معناداری آماری'],['تحلیل داده کیفی','آشنایی با کدگذاری و تحلیل مضمون'],['آموزش نرم‌افزار','SPSS، SmartPLS، AMOS و ابزارهای پژوهشی']].map((x,i)=><article className="card"><span className="service-icon">{React.createElement([BarChart3,ChartNoAxesColumnIncreasing,Microscope,Presentation][i])}</span><h3>{x[0]}</h3><p>{x[1]}</p><button className="text-link" onClick={()=>setLead(true)}>دریافت آموزش <ArrowLeft/></button></article>)}</section>{lead&&<div className="lead-inline"><h3>دریافت راهنمای آموزشی و مشاوره</h3><form onSubmit={e=>{e.preventDefault();let d={name:e.currentTarget.elements[0].value,phone:e.currentTarget.elements[1].value,date:new Date().toISOString()},a=JSON.parse(localStorage.getItem('adrin-leads')||'[]');localStorage.setItem('adrin-leads',JSON.stringify([d,...a]));notify('درخواست آموزشی ثبت شد.');setLead(false)}}><input required placeholder="نام و نام خانوادگی"/><input required type="tel" placeholder="شماره همراه"/><button className="btn gold small">ثبت درخواست</button><button type="button" className="text-link" onClick={()=>setLead(false)}>بستن</button></form></div>}</div></>}
